import java.io.Serializable;
import java.io.ObjectOutputStream;
import java.io.ObjectInputStream;
import java.io.FileOutputStream;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<Producto> lista = new ArrayList<>();
        lista.add(new Producto("Laptop", 1200));
        lista.add(new Producto("Mouse", 25));
        lista.add(new Producto("Teclado", 50));

        // Serialize
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("productos.dat"))) {
            oos.writeObject(lista);
            System.out.println("List serialized with " + lista.size() + " products");
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // Deserialize
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("productos.dat"))) {
            ArrayList<Producto> cargada = (ArrayList<Producto>) ois.readObject();
            for (Producto p : cargada) {
                System.out.println(p.nombre + ": $" + p.precio);
            }
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

class Producto implements Serializable {
    String nombre;
    double precio;
    Producto(String nombre, double precio) {
        this.nombre = nombre;
        this.precio = precio;
    }
}

